+vi.mock('./components/AutomationTab', () => stub('AutomationTab'));
+
+// Imported after the mocks are registered.
+const tabs = await import('./appTabs');
+
+const settle = () => new Promise((r) => setTimeout(r, 0));
+
+describe('appTabs', () => {
