+type Internals = {
+  deviceType: MeshCoreDeviceType;
+  connected: boolean;
+  repeaterPublicKey: string | null;
+  localNode: { publicKey: string } | null;
+  handleSerialData: (line: string) => void;
+  handleBridgeEvent?: unknown;
