+ * No media query on purpose: wrapping only happens when a row is too narrow,
+ * so the desktop layout is unchanged and a phone in landscape (wider than any
+ * max-width breakpoint) is covered too.
+ */
+
+.wrapRow {
+  flex-wrap: wrap;
