+
+/*
+ * A flex: 1 text field has a flex-basis of 0, so on a wrapping row it would
+ * shrink to a sliver next to its siblings. This floor makes it claim a usable
+ * width, and wrap to its own line when that does not fit. min() keeps the
+ * floor from ever exceeding the row itself.
+ */
+.growField {
+  min-width: min(100%, 9rem);
+}
