+    await vi.advanceTimersByTimeAsync(30_000);
+    await vi.runAllTimersAsync();
+    const r2 = await p2;
+    expect(r2.success).toBe(true);
+    expect(conn.sentFrames.length).toBe(2);
+    expect(warnSpy).toHaveBeenCalledWith(
