+
+const MYSQL_CREATE = `
+  DROP TABLE IF EXISTS packet_log;
+  CREATE TABLE packet_log (
+    id SERIAL PRIMARY KEY,
+    packet_id BIGINT,
+    timestamp BIGINT NOT NULL,
+    from_node BIGINT NOT NULL,
