+    // getRecentMessages honours the sourceId filter.
+    getPrimaryMeshtasticManager: () => ({
+      getRecentMessages: async (_limit: number, sid?: string) =>
+        sid ? (recentBySource[sid] ?? []) : allRecent,
+    }),
