+}
+
+.links {
+  display: flex;
+  flex-wrap: wrap;
+  gap: 12px;
+  margin-top: 2px;
+}
+
+.links a {
+  color: var(--color-accent);
+  text-decoration: underline;
+}
+
+.links a:hover {
+  color: var(--color-accent-hover);
+}
