+    const path = prefix ? `${prefix}.${k}` : k;
+    if (typeof v === 'string') out[path] = v;
+    else if (v && typeof v === 'object' && !Array.isArray(v)) {
+      Object.assign(out, leafStrings(v as Record<string, unknown>, path));
+    }
+  }
+  return out;
