+    expect(manager.localNodeInfo.firmwareVersion).toBe(FIRMWARE);
+    expect(manager.isLocalNodeBridged()).toBe(true);
+    expect(mockUpsertNodeAsync).not.toHaveBeenCalled();
+  });
