+/**
+ * SearchableSelect (#4512). Sized to sit inline with the native `<select>`s it
+ * replaces in `.packet-filters`, which set `flex: 1; min-width: 150px`.
+ * Colours are Catppuccin tokens so the control themes with everything else.
+ */
+
+.root {
+  position: relative;
+  flex: 1;
+  min-width: 150px;
+  display: flex;
+}
+
+.input {
+  /* Matches `.packet-filters select` so the row stays visually even. */
+  width: 100%;
+  padding: 6px 10px;
+  border: 1px solid var(--ctp-surface2);
+  border-radius: var(--radius-sm);
+  background: var(--ctp-base);
+  color: var(--ctp-text);
+  font-size: 13px;
+  font-family: inherit;
+}
+
+/* Only when the clear button is present, so the text is not pushed off-centre
+   in the common unfiltered case. */
+.hasClear {
+  padding-right: 30px;
+}
+
+.input::placeholder {
+  color: var(--ctp-subtext0);
+}
+
+.input:focus {
+  outline: none;
+  border-color: var(--ctp-blue);
+}
+
+.input:disabled {
+  opacity: 0.6;
+  cursor: not-allowed;
+}
+
+.clear {
+  position: absolute;
+  right: 6px;
+  top: 50%;
+  transform: translateY(-50%);
+  display: flex;
+  align-items: center;
+  justify-content: center;
+  /* 24px keeps the tap target usable on a phone without crowding the text. */
+  width: 24px;
+  height: 24px;
+  padding: 0;
+  border: none;
+  border-radius: var(--radius-sm);
+  background: transparent;
+  color: var(--ctp-subtext0);
+  font-size: 16px;
+  line-height: 1;
+  cursor: pointer;
+}
+
+.clear:hover {
+  background: var(--ctp-surface1);
+  color: var(--ctp-text);
+}
+
+.list {
+  position: absolute;
+  top: calc(100% + 2px);
+  left: 0;
+  right: 0;
+  /* Above the packet table's sticky header, which sits in the low tens. */
+  z-index: 1000;
+  margin: 0;
+  padding: 4px 0;
+  list-style: none;
+  max-height: 280px;
+  overflow-y: auto;
+  background: var(--ctp-surface0, #313244);
+  border: 1px solid var(--ctp-surface2);
+  border-radius: var(--radius-sm);
+  box-shadow: 0 6px 18px rgb(0 0 0 / 35%);
+}
+
+.option {
+  padding: 6px 10px;
+  font-size: 13px;
+  color: var(--ctp-text);
+  cursor: pointer;
+  white-space: nowrap;
+  overflow: hidden;
+  text-overflow: ellipsis;
+}
+
+/* Keyboard/pointer highlight. Kept distinct from `.selected` so arrowing
+   through the list never hides which option is currently in effect. */
+.active {
+  background: var(--ctp-surface1, #45475a);
+}
+
+.selected {
+  color: var(--ctp-blue);
+  font-weight: 600;
+}
+
+.empty,
+.more {
+  padding: 6px 10px;
+  font-size: 12px;
+  color: var(--ctp-subtext0);
+  font-style: italic;
+  cursor: default;
+}
