+
+  const stub: LayerStub = { bindPopup: vi.fn(), bindTooltip: vi.fn() };
+  const last = mocks.capturedGeoJsonProps[mocks.capturedGeoJsonProps.length - 1];
+  (last.onEachFeature as OnEachFeature)(
