+            name: 'Repeater One',
+            adv_type: 2, // Repeater
+            latitude: 37.7749,
+            longitude: -122.4194,
+            last_advert: 0,
+          },
+        ],
+      };
+    }
+    return { id: '1', success: true, data: {} };
+  };
+
+  return { manager: m, bridgeCalls };
