+  it('includes columns added by recent migrations (e.g. telemetry.rxSnr — migration 089)', () => {
+    t = createTestDb();
+    const cols = (t.sqlite.prepare('PRAGMA table_info(telemetry)').all() as { name: string }[]).map((c) => c.name);
+    expect(cols).toContain('rxSnr');
