+vi.mock('./utils/dbNodeMapper.js', () => ({
+  loadAllNodesAsDeviceInfo: (...args: unknown[]) => loadAllNodesAsDeviceInfo(...args),
+}));
+
+vi.mock('../utils/logger.js', () => ({
+  logger: { info: vi.fn(), warn: vi.fn(), error: vi.fn(), debug: vi.fn() },
+}));
+
