+    const parts = [(0x02 << 2) | 0x02, 0xff, 0x12, 0x34, 0xde, 0xad];
+    const rawHex = parts.map((b) => b.toString(16).padStart(2, '0')).join('');
+    render(
+      <MeshCorePacketDetailModal
+        packet={baseEvent({ payloadType: 0x02, rawHex, payloadSize: parts.length })}
